<div class="page-title"><h1>Detalle de venta</h1><p>Comprobante <?= htmlspecialchars(($sale["serie"] ?? "") . "-" . str_pad((string)($sale["correlativo"] ?? ""), 8, "0", STR_PAD_LEFT), ENT_QUOTES, "UTF-8") ?></p></div>
