<section class="panel sale-receipt">
    <div class="section-toolbar"><div><h2><?= htmlspecialchars($sale["comprobante"], ENT_QUOTES, "UTF-8") ?> <span class="status-badge <?= (int)$sale["estado"] === 1 ? "is-active" : "is-muted" ?>"><?= (int)$sale["estado"] === 1 ? "Activa" : "Anulada" ?></span></h2><p><?= htmlspecialchars(date("d/m/Y H:i", strtotime($sale["fecha"])), ENT_QUOTES, "UTF-8") ?> · <?= htmlspecialchars($sale["vendedor"], ENT_QUOTES, "UTF-8") ?></p></div><a class="btn btn-light" href="index.php?route=module/ventas">Volver a ventas</a></div>
    <p class="receipt-customer"><strong>Cliente:</strong> <?= htmlspecialchars($sale["cliente"] ?: "Cliente general", ENT_QUOTES, "UTF-8") ?><?= $sale["nrodocumento"] ? " · " . htmlspecialchars($sale["nrodocumento"], ENT_QUOTES, "UTF-8") : "" ?> · <strong>Pago:</strong> <?= ($sale["formapago"] ?? "C") === "R" ? "Credito" : "Contado" ?></p>
    <div class="table-wrap"><table class="data-table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio unitario</th><th>Importe</th></tr></thead><tbody><?php foreach ($sale["detalles"] as $line): ?><tr><td><?= htmlspecialchars($line["producto"], ENT_QUOTES, "UTF-8") ?></td><td><?= number_format((float)$line["cantidad"], 2) ?> <?= htmlspecialchars($line["unidad_nombre"], ENT_QUOTES, "UTF-8") ?></td><td>S/ <?= number_format((float)$line["pventa"], 2) ?></td><td>S/ <?= number_format((float)$line["total"], 2) ?></td></tr><?php endforeach; ?></tbody></table></div>
    <div class="receipt-totals"><span>Gravado <strong>S/ <?= number_format((float)$sale["total_gravado"], 2) ?></strong></span><span>Exonerado <strong>S/ <?= number_format((float)$sale["total_exonerado"], 2) ?></strong></span><span>Inafecto <strong>S/ <?= number_format((float)$sale["total_inafecto"], 2) ?></strong></span><span>IGV incluido <strong>S/ <?= number_format((float)$sale["total_igv"], 2) ?></strong></span><span class="receipt-grand-total">Total <strong>S/ <?= number_format((float)$sale["total"], 2) ?></strong></span></div>
